using UnityEngine;
using UnityEditor;
public static class JewelUiOpenGameView {
 public static string Run() {
 var type=typeof(Editor).Assembly.GetType("UnityEditor.GameView");
 var window=EditorWindow.GetWindow(type,false,"Game",false);
 window.Show();window.Repaint();EditorApplication.QueuePlayerLoopUpdate();
 return "Game View opened for edit-mode UI layout capture; Play Mode remains stopped";
 }
}
